/**
 * @addtogroup afw_object_interface afw_object
 *
 * Adaptive object: named properties, meta, path, and object-type driven
 * behavior. Prefer afw_object_create* helpers over raw layout; use
 * afw_object_*() macros for get/set/release and related calls.
 * Objects may be const (permanent) or mutable (often via sessions).
 * Meta (afw_object_meta) drives validation and UI; see group afw_object.
 *
 * @{
 */


/**
 * @brief Public instance layout for interface `afw_object`.
 *
 * API type name is `afw_object_t` (see opaques).
 * Call methods with `afw_object_<method>(…)` macros.
 * Implementations often embed this as the first field of
 * a larger self struct in .c files.
 */
struct afw_object_s {
    const afw_object_inf_t *inf;

    /**
     * This is the pool containing the object. This will be NULL if the
     * object is a const object.
     * 
     * This pool can be use to allocate memory that will last for the life
     * of the object and to register callback functions to call when the
     * object is released.
     * 
     * Depending on the afw_object implementation, this may be a subpool
     * of the pool the object was created in. If it is a subpool, the
     * release() method will release the subpool.
     */
    const afw_pool_t * p;

    /**
     * The adaptive value associated with this object instance. The lifetime
     * of this value is the same as the lifetime of the object.
     */
    const afw_value_t * value;

    /**
     * This is the meta associated with this object. See afw_object_meta.h
     * for more information.
     */
    afw_object_meta_t meta;
};

